"""Authored sector briefs composed with six bounded, versioned capability patterns.
These are starter exercise assumptions, not validated procedures or regulatory advice.
"""
import json,csv,pathlib
ROOT=pathlib.Path(__file__).parent
# sector, site, primary role, role responsible for approval, authoritative plan, disruption, scarce resource, critical function
sectors=[
('Incident management','Regional coordination center','Duty officer','Incident Commander','Incident Management Plan','conflicting field reports after severe weather','two verified response teams','a common operating picture'),
('Healthcare','North Campus hospital','Hospital command duty officer','Hospital Incident Commander','Emergency Operations Plan','a utility interruption affecting a clinical support area','one verified facilities response team','priority clinical support services'),
('Pipeline operations','Riverbend pipeline control center','Qualified Individual / alternate','designated Qualified Individual','Pipeline Response Plan','a reported release with location and impact still being verified','one contracted response team','safe incident coordination'),
('Oil, gas & marine','Harbor terminal','Terminal response coordinator','designated Qualified Individual','Facility Response Plan','a reported sheen near the transfer area','one verified containment support team','terminal incident coordination'),
('Electric utilities','District control center','Utility duty manager','System Incident Lead','Utility Emergency Response Plan','storm damage reports across two service areas','two restoration assessment crews','priority restoration coordination'),
('Water & wastewater','Central treatment works','Utility response coordinator','Utility Incident Lead','Utility Emergency Response Plan','loss of a monitored process and uncertain service impact','one verified maintenance crew','essential water service coordination'),
('Manufacturing','West production campus','Plant duty manager','Plant Incident Lead','Site Emergency Response Plan','a process interruption with conflicting equipment reports','one qualified maintenance team','safe continuity of critical production support'),
('Higher education','University main campus','Campus emergency coordinator','Campus Incident Lead','Campus Emergency Operations Plan','a campus utility outage during occupied hours','two campus support teams','student and staff support services'),
('K–12 education','District learning center','District duty administrator','District Incident Lead','District Emergency Operations Plan','severe weather and uncertainty about campus access','one verified transport coordination team','student accountability and continuity'),
('Local government','Municipal coordination center','Municipal duty officer','Emergency Management Director','Municipal Emergency Operations Plan','flooding reports and interrupted municipal services','two verified public works teams','priority public services'),
('Law enforcement & security','Public safety coordination center','Watch supervisor','authorized Incident Commander','Agency Incident Management Plan','an access-control alarm and conflicting witness reports','one verified coordination team','safe public safety coordination'),
('Facilities & property','Multi-tenant office campus','Facilities duty supervisor','Site Incident Lead','Facility Emergency Action Plan','a building-system failure affecting an occupied zone','one verified building support team','safe facility support services'),
('Financial services','Regional service office','Business continuity coordinator','Crisis Management Lead','Business Continuity Plan','loss of an essential service platform during business hours','one verified recovery team','priority customer services'),
('Cyber & technology','Digital operations center','Cyber incident coordinator','Cyber Incident Lead','Cyber Incident Response Plan','an account-compromise alert with uncertain business impact','one verified incident investigation team','essential digital services'),
('Transport & logistics','Regional logistics hub','Operations duty manager','Logistics Incident Lead','Operational Continuity Plan','a transport-system disruption with conflicting route reports','two verified logistics support teams','priority movement coordination'),
('Public venues & events','Civic event venue','Venue duty manager','Venue Incident Lead','Event Emergency Action Plan','a severe-weather warning and changing crowd access conditions','one verified venue support team','safe attendee support and accountability'),
]
patterns=[
{'id':'escalate','name':'Notification & escalation','phase':'Response','department':'Command / duty management','minutes':8,'role':'Duty officer','objective':'Route a time-bound initial notification to the authorized primary or alternate, preserve uncertainty, and establish a next update.','task':'Identify the appropriate recipient and escalation path.','key':'authority','criterion':'Used the current authorized escalation path'},
{'id':'verify','name':'Situation assessment','phase':'Response','department':'Planning / situation','minutes':10,'role':'Situation coordinator','objective':'Reconcile conflicting reports using provenance, distinguish known from unverified information, and issue a defensible operational update.','task':'Select the record that can support the operational picture.','key':'verified','criterion':'Retained source, time and verification status'},
{'id':'continuity','name':'Continuity & protective decisions','phase':'Preparedness / response','department':'Business continuity / operations','minutes':12,'role':'Continuity coordinator','objective':'Recommend an authorized continuity or protective measure with its dependencies, limitations, and an explicit review checkpoint.','task':'Choose the authorized interim action without treating an assumption as fact.','key':'bounded','criterion':'Selected a bounded action with dependencies'},
{'id':'resources','name':'Resource accountability','phase':'Response','department':'Planning / resources','minutes':10,'role':'Resources Unit recorder','objective':'Reconcile resource status from current evidence and route assignment decisions to the authorized operational lead.','task':'Record actual readiness, then identify who can authorize assignment.','key':'unverified','criterion':'Did not convert unverified availability into deployable capacity'},
{'id':'communicate','name':'Crisis communications','phase':'Response','department':'Communications / public information','minutes':8,'role':'Communications coordinator','objective':'Prepare a factual holding update for the approved review path without overstating impacts, causes, or restoration times.','task':'Select a release posture consistent with the verified information.','key':'review','criterion':'Retained uncertainty and followed release authority'},
{'id':'handover','name':'Handover & recovery','phase':'Recovery','department':'Command / recovery coordination','minutes':12,'role':'Relieving team coordinator','objective':'Transfer an accurate status picture with an acknowledged owner, unresolved dependencies, and the next verification point.','task':'Select the handover condition supported by the evidence.','key':'open','criterion':'Kept unresolved work open with accountable follow-up'},
]
# Unique sector-facing titles; each row contains one scenario for each capability pattern.
titles=[
['The first ten minutes','Two reports, one picture','Activate the coordination fallback','Checked in is not available','The unconfirmed impact statement','The unfinished operational period'],
['The clinical support escalation','Which outage report is current?','Continuity without assumed capacity','The team that has not checked in','A patient-facing holding update','The unresolved hospital dependency'],
['Reach the QI or the alternate','Release location not yet confirmed','The control-center continuity decision','The contracted team status gap','The first spill-related holding line','Transfer the open response commitment'],
['The terminal notification chain','Sheen reports that do not agree','A bounded terminal continuity decision','The arriving resource with no verification','What can the terminal confirm?','The next-shift terminal brief'],
['Escalate a priority service impact','The stale restoration map','Protect the priority-service dependency','Two crews, three reported needs','The restoration time nobody confirmed','The district restoration handover'],
['The first utility impact notification','Telemetry is not field confirmation','Maintain a bounded service workaround','The maintenance crew status conflict','An unverified service-impact claim','Transfer the unresolved utility condition'],
['Escalation beyond the production desk','Yesterday’s equipment status','Continuity without bypassing authority','The resource listed in two places','The premature return-to-normal message','The open defect at shift change'],
['The campus duty officer is unavailable','One campus, conflicting reports','The alternate student-support location','Campus support is not yet checked in','The campus-wide holding update','An unowned campus recovery action'],
['Reach the district decision authority','Which campus access report is verified?','Continuity with student-accountability constraints','Transport capacity is not confirmed','The message to families is not approved','Transfer the unresolved accountability issue'],
['The city notification window','Reconciling two neighborhood reports','The essential municipal service decision','Public works status before commitment','The public update with a missing fact','Handover before the coordination shift ends'],
['An alarm is not a confirmed incident','The witness and the verified report','An authorized protective recommendation','The unit status that needs reconciliation','The statement that goes beyond evidence','The unresolved public safety handover'],
['The building duty contact does not answer','The conflicting building-system reports','A protective recommendation with limits','The contractor listed as ready','What tenants can safely be told','The outstanding building dependency'],
['The service interruption escalation','Business impact is still uncertain','The continuity workaround decision','Recovery support is not yet available','A customer update without a false ETA','The open continuity exception'],
['The cyber-to-business escalation','An alert is not confirmed scope','Continuity with an unverified dependency','The responder capacity mismatch','A cyber holding statement under review','The investigation is not ready to close'],
['The logistics escalation path','Two route reports, one source gap','Protecting a priority movement dependency','The support team that cannot be assumed','The partner update with no verified ETA','Handover of the delayed priority movement'],
['The venue warning escalation','The access map is out of date','A bounded attendee-support decision','Support capacity before commitment','The attendee message needs approval','The event does not end the open action'],
]
records=[]
for si,s in enumerate(sectors):
    sector,site,duty,authority,plan,disruption,resource,function=s
    for pi,p in enumerate(patterns):
        n=si*6+pi+1
        scenario={**p,'id':f'TRG-{n:03d}','pattern':p['id'],'title':titles[si][pi],'sector':sector,'facility':site,'role':duty if pi==0 else p['role'],'authority':authority,'plan':plan,'hazard':disruption.split(' with ')[0],'trigger':f'EXERCISE ONLY. An initial report from {site} describes {disruption}. You are responsible for {p["name"].lower()} within your delegated role.','resource':resource,'function':function,'site':site,'status':'Starter • review required','version':'1.0.0','planSection':'Exercise assumption § 4.2','channels':['Web','SMS preview','Voice preview','Email preview','External-task preview'],'variants':['Baseline','Primary unavailable','Conflicting reports'],'review':'Authored starter. Not independently validated. Organization plan, jurisdiction, authority and thresholds must be reviewed before operational use.','sourceType':'Authored exercise assumptions; not an extracted organizational procedure.'}
        records.append(scenario)
(ROOT/'catalog.js').write_text('/* Authored starter content; see docs/CONTENT_STANDARD.md. */\nwindow.TRG_CATALOG='+json.dumps(records,separators=(',',':'),ensure_ascii=False)+';\nwindow.TRG_PATTERNS='+json.dumps(patterns,separators=(',',':'))+';\n',encoding='utf8')
(ROOT/'assets'/'catalog.json').write_text(json.dumps(records,indent=2,ensure_ascii=False),encoding='utf8')
with (ROOT/'assets'/'scenario_catalog.csv').open('w',newline='',encoding='utf-8-sig') as f:
    fields=['id','title','sector','pattern','name','role','department','phase','facility','hazard','plan','planSection','minutes','objective','trigger','authority','status','version','review']
    w=csv.DictWriter(f,fieldnames=fields,extrasaction='ignore');w.writeheader();w.writerows(records)
print(f'Authored {len(records)} starter configurations; {len(patterns)} shared patterns; {len(sectors)} sectors')
